<script lang="ts">
	import { onMount } from 'svelte';
	import { displayDate, formatRuntime, genreLabels, tasteLabels, type CatalogBook, type Taste } from '$lib/catalog';
	import { shelfLabels, type ShelfEntry, type ShelfStatus } from '$lib/library';
	import Icon from './Icon.svelte';
	let { book, seriesBooks, entry, onclose, onshelf, onrating, onlike, onopen }: {
		book: CatalogBook; seriesBooks: CatalogBook[]; entry?: ShelfEntry; onclose: () => void;
		onshelf: (book: CatalogBook, status: ShelfStatus | '') => void; onrating: (book: CatalogBook, rating: number) => void;
		onlike: (book: CatalogBook) => void; onopen: (book: CatalogBook) => void;
	} = $props();
	let dialog: HTMLDialogElement;
	let failedImage = $state(false);
	onMount(() => { dialog.showModal(); });
	const contentLabels: Record<keyof CatalogBook['content'], string> = { sexualized: 'Sexualized cover / marketing', explicit: 'Explicit sexual content', harem: 'Harem / reverse harem', aiNarration: 'AI narration', aiWriting: 'Disclosed AI writing', quality: 'Listing quality concerns' };
</script>

<dialog bind:this={dialog} onclose={onclose} aria-labelledby="detail-title">
	<div class="detail-top"><span class="eyebrow">Book details</span><button class="icon-button" aria-label="Close book details" onclick={() => dialog.close()}><Icon name="close"/></button></div>
	<div class="detail-intro">
		<div class="detail-cover">{#if book.coverUrl && !failedImage}<img src={book.coverUrl} alt={`Cover of ${book.title}`} onerror={() => failedImage = true}/>{:else}<Icon name="book" size={64}/>{/if}</div>
		<div><div class="detail-genres">{book.subgenres.map(g => genreLabels[g] ?? g).join(' · ')}</div><h2 id="detail-title">{book.title}</h2><p class="detail-author">by {book.author}</p>
			{#if book.series}<p class="detail-series">{book.series}{book.seriesNumber != null ? ` · Book ${book.seriesNumber}` : ''}</p>{/if}
			<p class="detail-rating"><span>★</span> <strong>{book.rating?.toFixed(2) ?? 'Not yet rated'}</strong> <small>{book.ratingCount.toLocaleString()} Audible ratings</small></p>
			<label class="shelf-select">Your shelf<select value={entry?.status ?? ''} onchange={e => onshelf(book, e.currentTarget.value as ShelfStatus | '')}><option value="">Not on a shelf</option>{#each Object.entries(shelfLabels) as [key, label]}<option value={key}>{label}</option>{/each}</select></label>
			<div class="your-rating"><span>Your rating</span>{#each [1,2,3,4,5] as value}<button aria-label={`Rate ${value} ${value === 1 ? 'star' : 'stars'}`} class:filled={(entry?.rating ?? 0) >= value} onclick={() => onrating(book, entry?.rating === value ? 0 : value)}>★</button>{/each}</div>
		</div>
	</div>
	<div class="detail-body">
		<div class="detail-facts"><span><Icon name="calendar" size={16}/>{displayDate(book.releaseDate)}</span><span><Icon name="headphones" size={16}/>{formatRuntime(book.runtimeMinutes)}</span><span>{book.edition === 'dramatized' ? 'Dramatized audio' : book.edition === 'collection' ? 'Audio collection' : 'Audiobook'}</span></div>
		<p class="narrator">Narrated by {book.narrator || 'a narrator yet to be listed'}</p>
		<h3>About the book</h3><p class="description">{book.description || 'We’re still gathering a description for this book.'}</p>
		<div class="detail-buttons"><button class="primary-button" onclick={() => onlike(book)}><Icon name="sparkles" size={17}/>Similar books</button>{#if book.url}<a class="text-link" href={book.url} target="_blank" rel="noreferrer">View on Audible <Icon name="external" size={15}/></a>{/if}</div>
		{#if book.assessment}<section class="taste-section"><div class="section-heading"><h3>Reading traits</h3><span class="small-badge">Description estimate</span></div><div class="taste-bars">{#each Object.entries(book.assessment.taste) as [key, value]}{#if value && value.confidence >= 0.45}<div><span>{tasteLabels[key as Taste]}</span><div class="taste-track"><div style:width={`${Math.round(value.value * 100)}%`}></div></div></div>{/if}{/each}</div><p class="small-note">Estimated from the publisher’s description. Uncertain traits are left out.</p></section>{/if}
		<details class="content-notes"><summary>Content notes & source information <Icon name="down" size={16}/></summary><p class="small-note">“Unknown” means there isn’t enough evidence. It does not mean a book is free of that content. AI writing is only flagged when the source discloses it.</p>{#each Object.entries(book.content) as [key, signal]}<div class="signal"><div><strong>{contentLabels[key as keyof CatalogBook['content']]}</strong><span class:flagged={signal.verdict === 'present'}>{signal.verdict === 'unknown' || signal.confidence < 0.8 ? 'Unknown' : signal.verdict === 'present' ? 'Flagged' : 'Not indicated'} · {signal.source === 'vision' ? 'Cover assessment' : signal.source === 'jev' ? 'Jev estimate' : signal.source === 'publisher' ? 'Source metadata' : signal.source}</span></div><p>{signal.note}</p></div>{/each}<p class="small-note">{book.sources.map(s => `${s.name} · fetched ${displayDate(s.fetchedAt.slice(0,10))}`).join(' / ') || 'Source timestamp unavailable'}</p>{#if book.issues.length}<p class="small-note">Catalog notes: {book.issues.join(' · ')}</p>{/if}</details>
		{#if book.series && seriesBooks.length > 1}<section class="series-list"><h3>In {book.series}</h3><p class="small-note">{seriesBooks.length} catalogued editions. This series may have gaps.</p>{#each seriesBooks as sibling}<button class:current={sibling.id === book.id} onclick={() => onopen(sibling)}><span class="series-number">{sibling.seriesNumber ?? '—'}</span><span><strong>{sibling.title}</strong><small>{displayDate(sibling.releaseDate)}{sibling.edition !== 'audiobook' ? ` · ${sibling.edition}` : ''}</small></span><Icon name="chevron" size={15}/></button>{/each}</section>{/if}
	</div>
</dialog>

<style>
	dialog{border:1px solid var(--line);border-radius:6px;padding:0;background:var(--paper);color:var(--ink);width:min(780px,calc(100vw - 28px));max-height:90vh;position:fixed;margin:auto;box-shadow:0 20px 80px #17251c30}dialog::backdrop{background:#0008;}.detail-top{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;border-bottom:1px solid var(--line)}.detail-intro{display:grid;grid-template-columns:140px 1fr;gap:22px;padding:20px 24px}.detail-cover{background:transparent;display:grid;place-items:center;padding:0;align-self:start;aspect-ratio:1;color:var(--green)}.detail-cover img{width:100%;max-height:240px;object-fit:contain}.detail-genres{font-size:10px;letter-spacing:.05em;text-transform:uppercase;color:var(--green);line-height:1.6}h2{font:600 22px/1.3 var(--sans);margin:9px 0 8px}.detail-author{font-size:14px;color:var(--muted)}.detail-series{font-size:12px;color:var(--green);margin-top:9px}.detail-rating{display:flex;align-items:center;gap:6px;margin:15px 0}.detail-rating>span{color:var(--gold)}.detail-rating small{color:var(--muted);font-size:11px}.shelf-select{font-size:11px;display:flex;align-items:center;gap:12px;color:var(--muted)}select{flex:1;max-width:200px;background:var(--sage);color:var(--green);border:1px solid #cbd4c4;border-radius:5px;padding:9px 10px;font:600 12px var(--sans)}.your-rating{display:flex;gap:4px;align-items:center;margin-top:13px;font-size:11px;color:var(--muted)}.your-rating>span{margin-right:9px}.your-rating button{font-size:21px;padding:1px;border:0;background:transparent;color:#d4cfc0}.your-rating .filled{color:var(--gold)}.detail-body{padding:0 32px 32px}.detail-facts{display:flex;flex-wrap:wrap;gap:16px;font-size:12px;border-top:1px solid var(--line);padding-top:20px}.detail-facts span{display:flex;align-items:center;gap:7px}.narrator{font-size:12px;color:var(--muted);margin:10px 0 26px}h3{font:600 14px var(--sans);margin:0 0 12px}.description{font-size:14px;line-height:1.6;color:var(--ink);white-space:pre-line}.detail-buttons{display:flex;align-items:center;gap:24px;margin:24px 0 28px}.taste-section{padding:16px 0;border-top:1px solid var(--line)}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-heading h3{margin:0}.taste-bars{display:grid;grid-template-columns:1fr 1fr;gap:14px 28px;margin-top:20px}.taste-bars>div{display:flex;align-items:center;gap:12px;font-size:11px}.taste-bars span{width:95px;flex-shrink:0}.taste-track{height:5px;background:var(--line);width:100%;border-radius:4px;overflow:hidden}.taste-track>div{height:100%;background:var(--green);border-radius:4px}.small-note{color:var(--muted);font-size:11px;line-height:1.7;margin-top:14px}.content-notes{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0}summary{list-style:none;display:flex;align-items:center;justify-content:space-between;font-size:13px;font-weight:600;cursor:pointer}.signal{border-top:1px solid var(--line);padding:12px 0;margin-top:12px}.signal>div{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px}.signal strong{font-weight:500}.signal span{font-size:10px;color:var(--muted)}.signal .flagged{color:var(--rust)}.signal p{font-size:11px;line-height:1.5;color:var(--muted);margin-top:8px}.series-list{margin-top:24px}.series-list>button{background:transparent;border:0;border-bottom:1px solid var(--line);display:flex;gap:15px;align-items:center;width:100%;text-align:left;color:var(--ink);padding:13px 8px}.series-list>button.current{background:var(--sage)}.series-number{color:var(--muted);font:500 15px var(--serif);min-width:25px}.series-list strong{font-size:12px;display:block;font-weight:500}.series-list small{display:block;font-size:10px;color:var(--muted);margin-top:5px}.series-list :global(svg){margin-left:auto;flex-shrink:0}@media(max-width:600px){.detail-top{padding:12px 18px}.detail-intro{padding:22px 18px;grid-template-columns:95px 1fr;gap:15px}.detail-cover{padding:7px}h2{font-size:22px}.detail-body{padding:0 18px 24px}.detail-buttons{gap:16px;flex-wrap:wrap}.detail-rating{flex-wrap:wrap}.taste-bars{grid-template-columns:1fr}.section-heading{align-items:start;flex-direction:column}.signal>div{align-items:start;flex-direction:column}.your-rating{flex-wrap:wrap}}
</style>
